function pickNext(jobs) {
  let best = jobs[0];
  for (const job of jobs) {
    if (job.priority > best.priority || (job.priority === best.priority && job.added < best.added)) {
      best = job;
    }
  }
  return best.label;
}

const jobs = [
  { label: "normal", priority: 50, added: 1 },
  { label: "low", priority: 10, added: 2 },
  { label: "urgent", priority: 100, added: 3 },
  { label: "urgent 2", priority: 100, added: 4 },
];
console.log(pickNext(jobs));
console.log(pickNext(jobs.filter((job) => job.priority < 100)));
